// Generated by esquadro: do not edit. A resource of yours: what its list,
// form and page show, on top of what the model says (its meta).
import type { LucideIcon } from "lucide-react"
import type { ReactNode } from "react"
import type { FieldMeta, Rec, ResourceMeta } from "./meta.ts"

export interface ColumnOptions {
  label?: string
  /** Your own cell. */
  cell?: (record: Rec) => ReactNode
  /** Changed in the list itself: a choice or a checkbox at once, text on a click. */
  editable?: boolean
  /** Hidden until shown from the Columns menu. */
  hidden?: boolean
}

/** A column of the list: a field, or a field with options. */
export type Column = FieldMeta | ({ field: FieldMeta } & ColumnOptions)

/**
 * An action of yours, on a record: approve, publish, copy its message. It
 * changes fields (patch, after the fields of ask), copies text (copy) or an
 * image (copyImage), runs your code (run), or more than one, in that order:
 * copy, copyImage, patch, run.
 */
export interface Action {
  label: string
  icon?: LucideIcon
  /** Shown only when this answers true; the API still decides. */
  when?: (record: Rec) => boolean
  /** Your code. */
  run?: (record: Rec) => Promise<unknown> | unknown
  /** The fields it sets, by PATCH (If-Match): { status: "APPROVED" }, or what a function makes of the record. */
  patch?: Record<string, unknown> | ((record: Rec) => Record<string, unknown>)
  /** Fields of the form asked for first, in a small dialog, sent with the patch. */
  ask?: FieldMeta[]
  /** Text to copy: a message to paste elsewhere. */
  copy?: (record: Rec) => string
  /** The address of an image to copy, as an image: a picture to paste into WhatsApp. */
  copyImage?: (record: Rec) => string
  /** Its key, on the record in focus (the queue) or open: "1", "s". */
  key?: string
  /** Ask first, with this question. */
  confirm?: string
  /** Also on the records selected in the list, each in turn. */
  bulk?: boolean
  /** Shown in red: what removes or cannot be undone. */
  destructive?: boolean
}

/**
 * A resource's queue: the records of a filter as cards, one in focus, worked
 * with the keys of the actions; one an action takes out of the filter
 * leaves, and the next comes.
 */
export interface Queue {
  /** The records in it, by the API's filters: { status: "PENDING" }. */
  filter: Record<string, unknown>
  /** What each card shows: its picture, its title and some fields. */
  card?: { image?: FieldMeta; title?: FieldMeta; fields?: FieldMeta[] }
  /** Its tab's name: "Queue" by default. */
  label?: string
}

/** Records of another resource that point at this one: a category's products. */
export interface Relation {
  resource: Resource
  /** The other resource's key to this one: category_id. */
  param: string
  label?: string
}

/** A list of related records, on a record's page. */
export function relation(resource: Resource, param: string, options: { label?: string } = {}): Relation {
  return { resource, param, ...options }
}

/** What a resource shows, written in src/resources/<resource>.tsx. */
export interface ResourceDef {
  table: {
    columns: Column[]
    search?: boolean
    filters?: FieldMeta[]
    sort?: string
    /** Checkboxes to act on several records at once; on by default. */
    select?: boolean
    /**
     * Where the filters are: a drawer (the project's default, the spa's
     * filters option), a dialog, or a bar beside the search.
     */
    filterLayout?: "drawer" | "dialog" | "bar"
    /** Tabs above the list by an enum or a yes or no field, each with its count. */
    tabs?: FieldMeta
    /** A funnel in the header of each column the list filters by. */
    columnFilters?: boolean
  }
  form: FieldMeta[]
  /** The form in cards: a title, and the fields of each (of those in form). */
  sections?: { title: string; description?: string; fields: FieldMeta[]; side?: boolean }[]
  show?: FieldMeta[]
  /** The fields beside the picture on a record's page: the first short ones (not the title) by default. */
  summary?: FieldMeta[]
  actions?: Action[]
  /** A queue of the records of a filter, beside the table, worked with the keys of the actions. */
  queue?: Queue
  /** The field a record is called by (in titles and pickers). */
  title?: FieldMeta
  /**
   * A second line under a record's name in lists: a field (its category) or
   * what a function makes of the record.
   */
  subtitle?: FieldMeta | ((record: Rec) => string)
  /**
   * A record's picture, as a URL: beside its name in lists and on its page.
   * Without one, or when it has none, the first letters of its name.
   */
  image?: (record: Rec) => string | null | undefined
  /**
   * The lists of related records on a record's page. A function, so that
   * two resources can list each other; self is this resource, for the
   * records of its own that point at one (a comment's replies).
   */
  relations?: (self: Resource) => Relation[]
}

export interface Resource extends ResourceDef {
  meta: ResourceMeta
}

/** A resource: the model's meta, and what you decide it shows. */
export function resource(meta: ResourceMeta, def: ResourceDef): Resource {
  // A filter the API does not have would show a list it did not filter.
  const filters = def.table.filters?.filter((f) => {
    const ok = meta.filters.some(
      (p) => (p.param === f.name && (p.kind === "eq" || p.kind === "in")) || (p.param === `${f.name}_min` && p.kind === "min"),
    )
    if (!ok) console.warn(`${meta.name}: the API does not filter by ${f.name}: mark it @store(filter) in the model`)
    return ok
  })
  return { meta, ...def, table: { ...def.table, filters } }
}

/** A column with options: its label, your own cell, edited in the list. */
export function column(field: FieldMeta, options: ColumnOptions): Column {
  return { field, ...options }
}

export function columnField(c: Column): FieldMeta {
  return "field" in c ? c.field : c
}

export function columnOptions(c: Column): ColumnOptions {
  return "field" in c ? c : {}
}
